window.StrictDoc.search.nodesByMid = {"1":{"MID":"14ce2a416cd74d9f90647f5bfe47ddda","UID":"TVC-MO-001","RECORD_TYPE":"Objective","TITLE":"Maintain Powered Attitude","SUBTEAM_OWNER":"Systems","INDIVIDUAL_OWNER":"Systems Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Powered Ascent","FLIGHT_ATTEMPT":"Flight 1","OPEN_ITEM_STATUS":"None","STATUS":"Draft","STATEMENT":"Demonstrate that the vehicle can maintain attitude under nominal launch conditions.","RATIONALE":"This mission objective demonstrates the program goal of thrust-vector control during powered ascent.","_LINK":"TVC-MO-001"},"2":{"MID":"27eda2ca48d14ea6a4a3033c243d7e5b","UID":"TVC-MO-002","RECORD_TYPE":"Objective","TITLE":"Respond to Environmental Factors","SUBTEAM_OWNER":"Systems","INDIVIDUAL_OWNER":"Systems Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Powered Ascent","FLIGHT_ATTEMPT":"Flight 1","OPEN_ITEM_STATUS":"None","STATUS":"Draft","STATEMENT":"Demonstrate that the vehicle can maintain attitude in response to reasonable environmental factors, such as wind gusts. Other environmental factors include temperature, humidity, and pressure.","RATIONALE":"This mission objective demonstrates the program goal of thrust-vector control, even in response to expected environmental factors. Reasonable is based on the average expected conditions at the launch site. For example, a reasonable wind condition would be the average maximum gust over the course of a week.","_LINK":"TVC-MO-002"},"3":{"MID":"c9afe565a464410086d38407ab1f38e4","UID":"TVC-MO-003","RECORD_TYPE":"Objective","TITLE":"Capture Social Media Ready Content","SUBTEAM_OWNER":"Systems","INDIVIDUAL_OWNER":"Systems Lead","VEHICLE_CONFIGURATION":"All","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","STATUS":"Draft","STATEMENT":"Achieve social media ready video capture of all launch phases defined in program configuration, with at least two angles of each phase.","RATIONALE":"This mission objective supports the overall GNC mission of recruiting and training members for the future, with high-quality social media content an integral part of doing so.","_LINK":"TVC-MO-003"},"4":{"MID":"3a5cb37666b14beb9d05747b86e89cc6","UID":"TVC-MO-004","RECORD_TYPE":"Objective","TITLE":"Rapid Launch Turnaround","SUBTEAM_OWNER":"Systems","INDIVIDUAL_OWNER":"Systems Lead","VEHICLE_CONFIGURATION":"All","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","STATUS":"Draft","STATEMENT":"Achieve a rapid rocket launch turnaround capability, allowing for 3+ launches per launch day, assuming no major failures in any system.","RATIONALE":"This mission objective supports the overall GNC mission of rapid launch, reusability, iteration, and testing by allowing for multiple launches each launch day.","_LINK":"TVC-MO-004"},"5":{"MID":"9a59aa884b024751babcd868d70b2ccc","UID":"TVC-MO-005","RECORD_TYPE":"Objective","TITLE":"Capture Flight Data","SUBTEAM_OWNER":"Systems, Electrical, Software","INDIVIDUAL_OWNER":"Systems Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"Flight 1","OPEN_ITEM_STATUS":"None","STATUS":"Draft","STATEMENT":"Achieve data capture of all important flight parameters, including but not limited to raw sensor output, state estimation data, and state machine status.","RATIONALE":"This mission objective supports GNC's goal of iteration by providing data for flight analysis and iteration.","_LINK":"TVC-MO-005"},"6":{"MID":"18326be2d97f4cf5be24e7ec198a5562","UID":"TVC-MO-006","RECORD_TYPE":"Objective","TITLE":"Recover Vehicle Safely","SUBTEAM_OWNER":"Systems, Structures, Electrical, Software","INDIVIDUAL_OWNER":"Systems Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Parachute Descent","FLIGHT_ATTEMPT":"Flight 1","OPEN_ITEM_STATUS":"None","STATUS":"Draft","STATEMENT":"Achieve a soft landing of the rocket under parachute with nominal mission parameters.","RATIONALE":"This mission objective supports GNC's goal of rapid launch and reusability, along with preservation of data, and limitation of resources used.","_LINK":"TVC-MO-006"},"7":{"MID":"99a837dd8ca94d27b71885f8a151bffa","UID":"TVC-MO-007","RECORD_TYPE":"Objective","TITLE":"Vehicle Structural Integrity","SUBTEAM_OWNER":"Structures","INDIVIDUAL_OWNER":"Structures Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"Flight 1","OPEN_ITEM_STATUS":"None","STATUS":"Draft","STATEMENT":"Demonstrate that the vehicle can sustain all loads without structural damage or disassembly, under conditions from all mission phases. This includes any loads as the rocket impacts the ground during recovery.","RATIONALE":"This mission objective supports GNC's goal of rapid launch and reusability, along with reducing program costs by allowing components to be reused.","_LINK":"TVC-MO-007"},"8":{"MID":"dbdb2f09f1314942adf2b40e31138a37","UID":"TVC-MC-001","RECORD_TYPE":"Constraint","TITLE":"Vehicle Altitude Condition","SUBTEAM_OWNER":"Systems","INDIVIDUAL_OWNER":"Systems Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","STATUS":"Draft","STATEMENT":"The vehicle shall comply with launch site regulations that the rocket must get off the ground and shall not hit the ground while under motor power, while under nominal rocket conditions.","RATIONALE":"This mission constraint ensures that the rocket parameters will allow it to actually get off the ground and stay in the air for the full extent of the motor burn, assuming the controls system keeps the rocket vertical.","_LINK":"TVC-MC-001"},"9":{"MID":"3ba1c82016cb4ff0ba7d12aafb2c61c8","UID":"TVC-MO-008","RECORD_TYPE":"Objective","TITLE":"Controls Shutoff Condition","SUBTEAM_OWNER":"Controls","INDIVIDUAL_OWNER":"Controls Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","STATUS":"Draft","STATEMENT":"Demonstrate that the vehicle can shut off controls when determined that the rocket attitude can not be recovered. Shutting off controls is defined as actuating the gimbal to its known 0 position, then cutting power to the gimbal actuators.","RATIONALE":"This mission objective ensures that the rocket does not try to control attitude at a point when it can no longer do so, and it may be unsafe to continue attempting to do so. Lower level requirement more clearly defines the conditions where rocket attitude can not be recovered.","_LINK":"TVC-MO-008"},"10":{"MID":"ca941c0226e1443e9ff8e7f5c2c8840f","UID":"TVC-MO-009","RECORD_TYPE":"Objective","TITLE":"Closed Loop Controls","SUBTEAM_OWNER":"Controls","INDIVIDUAL_OWNER":"Controls Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","STATUS":"Draft","STATEMENT":"Demonstrate that the vehicle can use closed loop controls to control the rocket atttidue under power.","RATIONALE":"This mission objective is fundamental to GNCs mission of using active controls.","_LINK":"TVC-MO-009"},"11":{"MID":"8febd5efd5a342168fbd3f8763776df5","UID":"TVC-MO-010","RECORD_TYPE":"Objective","TITLE":"Onboard state machine","SUBTEAM_OWNER":"Controls","INDIVIDUAL_OWNER":"Controls Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","STATUS":"Draft","STATEMENT":"Demonstrate that the vehicle software uses a state machine, with clearly defined state transitions and no undefined states, for all flight conditions.","RATIONALE":"A state machine is essential to providing clear activities for each phase of the mission, helping to avoid things such as large if-else statements, among other things.","_LINK":"TVC-MO-010"},"12":{"MID":"3b98736717b84096a80c007ac88ccf70","UID":"TVC-MC-002","RECORD_TYPE":"Constraint","TITLE":"NAR Material Standards","SUBTEAM_OWNER":"Systems","INDIVIDUAL_OWNER":"Systems Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","STATUS":"Draft","STATEMENT":"The vehicle shall comply with NAR model rocket safety code (https://www.nar.org/ModelRocketSafetyCode) for materials, not including any metal in rocket externals. ","RATIONALE":"GNC launches at NAR launch sites, generally, and it is preferred to comply with as many standards as reasonable. One of these is materials, which should also be a reasonable constraint to meet.","_LINK":"TVC-MC-002"},"13":{"MID":"b31dadcebe254695ba9d3e87b633edb7","UID":"TVC-MC-003","RECORD_TYPE":"Constraint","TITLE":"Range Safety Analysis","SUBTEAM_OWNER":"Systems","INDIVIDUAL_OWNER":"Systems Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"TBD","RESOLUTION_OWNER":"Controls Leads","RESOLUTION_PLAN":"Controls should use a completed GNCSim architecture to simulate the exact launch range. TVC-REQ-030 has a clearer resolution plan that should be referenced.","RESOLUTION_DUE_DATE":"September 31st","STATUS":"Draft","STATEMENT":"The mission shall use simulation for establishing a maximum [TBD_LaunchRange] area based on maxumum predicted launch dispersion of the rocket.","RATIONALE":"GNC is dedicated to maintaing safe launches, and it is imperative that during launch a safe range is established.","_LINK":"TVC-MC-003"},"14":{"MID":"30216fb53bb84ad1aee4305381d62a1e","UID":"TVC-MO-011","RECORD_TYPE":"Objective","TITLE":"Removing launch rail","SUBTEAM_OWNER":"Systems","INDIVIDUAL_OWNER":"Systems Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"Flights 4+","OPEN_ITEM_STATUS":"None","STATUS":"Draft","STATEMENT":"Demonstrate that the vehicle can nominally launch under no-rail conditions.","RATIONALE":"In order to truly demonstrate stabilized flight, the first phase of flight, takeoff, should be done without a launch rail. This requirement is limited to later flights as historically GNC has struggled more with takeoff from the pad.","_LINK":"TVC-MO-011"},"15":{"MID":"22fc543fdbcf4a82b12d369e48bf70d3","UID":"TVC-MO-012","RECORD_TYPE":"Objective","TITLE":"Protection against accidents","SUBTEAM_OWNER":"Systems","INDIVIDUAL_OWNER":"Systems Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Pre-Launch","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","STATUS":"Draft","STATEMENT":"Demonstrate that the vehicle can operate under the conditions of common, low-level mistakes that have been made.  ","RATIONALE":"The team makes mistakes all the time. We accidentally plug in a wrong battery, we drop items, we forget something at home. It is worth it to consider these common mistakes, and, if easy solutions exist, implement these solutions to give us a better chance of insulating the launch against mistakes.","_LINK":"TVC-MO-012"},"16":{"MID":"9dcef7dbd77f4012bf251c23f8e691aa","UID":"TVC-MO-013","RECORD_TYPE":"Objective","TITLE":"Control Initial Delay","SUBTEAM_OWNER":"Software","INDIVIDUAL_OWNER":"Software Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Pre-Launch","FLIGHT_ATTEMPT":"Flights 1-3","OPEN_ITEM_STATUS":"None","STATUS":"Draft","STATEMENT":"Demonstrate that the vehicle can clear the launch rail before beginning to actuate the gimbal.","RATIONALE":"The rocket should not attempt to control itself until it has cleared the rail, as the rail is controlling the attitude at this point, and gimballing is likely to just cause more friction between the rail buttons and the rail.","_LINK":"TVC-MO-013"},"17":{"MID":"b50e4cb3c9144fa1a75d99a7035d6a6c","UID":"TVC-REQ-001","LEVEL":"L1","REQUIREMENT_TYPE":"Functional","TITLE":"Ease of Integration","APPLICABLE_SUBSYSTEM":"Airframe, Propulsion, Actuation, Recovery","SUBTEAM_OWNER":"Systems, Structures, Electrical","INDIVIDUAL_OWNER":"Systems Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Pre-Launch","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Demonstration","STATUS":"Draft","STATEMENT":"The vehicle shall be fully integrated, launched, and recovered within 2 hours under nominal conditions.","RATIONALE":"This requirement decomposes TVC-MO-004, specifically focusing on the vehicle, and giving a specific timeframe for complete turnaround. Most launch sites are open from 10 AM to 4 PM, so 2 hours is the absolute maximum each launch may take. This does not take into account failures, which are varied and more specifically specified in the Concept of Operations documents.","_LINK":"TVC-REQ-001"},"18":{"MID":"efe913a076044b61bb61d62195a54881","UID":"TVC-REQ-002","LEVEL":"L1","REQUIREMENT_TYPE":"Functional","TITLE":"Flight Computer Fire Wire","APPLICABLE_SUBSYSTEM":"Avionics, Recovery, Power","SUBTEAM_OWNER":"Electrical","INDIVIDUAL_OWNER":"Electrical Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Parachute Descent","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Test","STATUS":"Draft","STATEMENT":"The on board rocket avionics shall have the ability to set off fire wire, with at least 3 channels available to fire.","RATIONALE":"This derived requirement ensures the rocket avionics will be able to support redundant single-deploy recovery, along with an extra channel to support landing operations in the future, such as fire wire to release landing legs.","_LINK":"TVC-REQ-002"},"19":{"MID":"381c1f4b33914f3fae8341cce6e734d2","UID":"TVC-REQ-003","LEVEL":"L1","REQUIREMENT_TYPE":"Functional","TITLE":"Flight Computer Data Logging","APPLICABLE_SUBSYSTEM":"Avionics, Power, Flight_Software","SUBTEAM_OWNER":"Electrical, Software","INDIVIDUAL_OWNER":"Electrical Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Test","STATUS":"Draft","STATEMENT":"The Flight Computer shall log all determined relevant flight data on an onboard SD-Card. This includes all raw sensor data (IMU, Barometer, other peripherals), relevant state estimation outputs (State Vector), actuator command outputs, individual control outputs, timestamps for each set of data, and current state of the state machine.","RATIONALE":"This decomposes TVC-MO-005 to apply to flight computer onboard data logging, along with a more specific set of data to collect.","_LINK":"TVC-REQ-003"},"20":{"MID":"f479537d0cf245b386a4a3324ce15d64","UID":"TVC-REQ-004","LEVEL":"L1","REQUIREMENT_TYPE":"Functional","TITLE":"Relevant Telemetry Data","APPLICABLE_SUBSYSTEM":"Avionics, Power, Flight_Software, Ground_Systems","SUBTEAM_OWNER":"Electrical, Software","INDIVIDUAL_OWNER":"Electrical Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Test","STATUS":"Draft","STATEMENT":"The flight computer shall send relevant flight data to a ground station via telemetry data packets. This includes state estimation outputs (State Vector), actuator commands outputs, individual control outputs, timestamps since launch, and the current state of the state machine.","RATIONALE":"This decomposes TVC-MO-005 to apply to telemetry to the ground station, along with more specific information on what to send.","_LINK":"TVC-REQ-004"},"21":{"MID":"71a9637d046246b8a3aa6c0ac7d1e8b4","UID":"TVC-REQ-005","LEVEL":"L1","REQUIREMENT_TYPE":"Physical","TITLE":"Gimbal Minimum Angle","APPLICABLE_SUBSYSTEM":"Actuation","SUBTEAM_OWNER":"Structures","INDIVIDUAL_OWNER":"Structures Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Powered Ascent","FLIGHT_ATTEMPT":"Flight 1","OPEN_ITEM_STATUS":"TBD","RESOLUTION_OWNER":"Controls Lead","RESOLUTION_PLAN":"Controls subteam will use a completed GNCSim architecture, with an integrated model/simulation of the gimbal, in order to determine the minimum gimbal angle. The simulation shall prove that the minimum gimbal angle (along with other gimbal properties) provided allows the rocket to maintain attitude under environmental conditions. Simulation results must be produced before the gimbal CDR. If GNCSim is not finished/integrated in time to complete this task, off the shelf tools such as aeroVECTOR will be used in replacement.","RESOLUTION_DUE_DATE":"October 16th","VERIFICATION_METHOD":"Demonstration","STATUS":"Draft","STATEMENT":"The minimum actuation angle the gimbal shall be physically capable of is [TBD_GimAngle] degrees, in all directions (360 degrees).","RATIONALE":"Based on results from GNCSim dynamic analysis, this will help establish the minimum ange the gimbal is capable of in order for the rocket to be physically capable of maintaining attitude, a fundamental function the rocket must have in order to meet system goals.","_LINK":"TVC-REQ-005"},"22":{"MID":"ee69b5c9b70e431b867afc597ea83477","UID":"TVC-REQ-006","LEVEL":"L1","REQUIREMENT_TYPE":"Physical","TITLE":"Gimbal Minimum Velocity","APPLICABLE_SUBSYSTEM":"Actuation","SUBTEAM_OWNER":"Structures","INDIVIDUAL_OWNER":"Structures Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Powered Ascent","FLIGHT_ATTEMPT":"Flight 1","OPEN_ITEM_STATUS":"TBD","RESOLUTION_OWNER":"Controls Lead","RESOLUTION_PLAN":"Controls subteam will use a completed GNCSim architecture, with an integrated model/simulation of the gimbal, in order to determine the minimum gimbal velocity. The simulation shall prove that the minimum gimbal velocity (along with other gimbal properties) provided allows the rocket to maintain attitude under environmental conditions. Simulation results must be produced before the gimbal CDR. If GNCSim is not finished/integrated in time to complete this task, off the shelf tools such as aeroVECTOR will be used in replacement.","RESOLUTION_DUE_DATE":"October 16th","VERIFICATION_METHOD":"Test","STATUS":"Draft","STATEMENT":"The minimum velocity the gimbal shall be physically capable of is [TBD_GimVel] degrees/sec.","RATIONALE":"Based on results from GNCSim dynamic analysis, this will help establish the minimum speed the gimbal is capable of in order for the rocket to be physically capable of maintainin attitude, a fundamental function the rocket must have to meet system goals.","_LINK":"TVC-REQ-006"},"23":{"MID":"736f30d550b3484e97b8738ef291163c","UID":"TVC-REQ-007","LEVEL":"L1","REQUIREMENT_TYPE":"Physical","TITLE":"Gimbal Minimum Actuation Fidelity","APPLICABLE_SUBSYSTEM":"Actuation","SUBTEAM_OWNER":"Structures","INDIVIDUAL_OWNER":"Structures Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Powered Ascent","FLIGHT_ATTEMPT":"Flight 1","OPEN_ITEM_STATUS":"TBD","RESOLUTION_OWNER":"Controls Lead","RESOLUTION_PLAN":"Controls subteam will use a completed GNCSim architecture, with an integrated model/simulation of the gimbal, in order to determine the minimum gimbal fidelity. The simulation shall prove that the minimum gimbal fidelity (along with other gimbal properties) provided allows the rocket to maintain attitude under environmental conditions. Simulation results must be produced before the gimbal CDR. If GNCSim is not finished/integrated in time to complete this task, off the shelf tools such as aeroVECTOR will be used in replacement.","RESOLUTION_DUE_DATE":"October 16th","VERIFICATION_METHOD":"Test","STATUS":"Draft","STATEMENT":"The minimum actuation fidelity the gimbal shall be physically capable of is [TBD_TVCFid] degrees. This means the gimbal shall be able to actuate to positions that are multiples of the actuation fidelity.","RATIONALE":"Based on results from GNCSim dynamic analysis, this will help establish the minimum actuation fidelity the gimbal is capable of in order for the rocket to be physically capable of maintainin attitude, a fundamental function the rocket must have to meet system goals.","_LINK":"TVC-REQ-007"},"24":{"MID":"9d98e3b1fca741be93baea616d1762c9","UID":"TVC-REQ-008","LEVEL":"L2","REQUIREMENT_TYPE":"Safety","TITLE":"PCB Fire Wire Protection","APPLICABLE_SUBSYSTEM":"Avionics","SUBTEAM_OWNER":"Electrical","INDIVIDUAL_OWNER":"Electrical Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Pre-Launch","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Inspection","STATUS":"Draft","STATEMENT":"The flight computer shall support a physical inhibit/enable switch for the fire wire, with physical on-board feedback of inhibit/enable status that the microntroller can read.","RATIONALE":"Inhibiting the fire wire switch is an important safety feature to ensure safe operations while handling the rocket up until launch operations. Feedback ensures the team is aware of the state of the fire wire.","_LINK":"TVC-REQ-008"},"25":{"MID":"3423a1bb79474dba95b5dfe0beeafd81","UID":"TVC-REQ-009","LEVEL":"L1","REQUIREMENT_TYPE":"Design Constraint","TITLE":"PCB Test Points","APPLICABLE_SUBSYSTEM":"Avionics","SUBTEAM_OWNER":"Electrical","INDIVIDUAL_OWNER":"Electrical Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Inspection","STATUS":"Draft","STATEMENT":"For major board circuitry, such as the recovery circuit, it shall be possible to physically check voltage using test points on the board. Important power lines, recovery circuitry, microntroller debugging, interfaces (CAN, JTAG), and more should include test points.","RATIONALE":"This is both an important board design feature to allow for debugging in the case of failures during testing, and any last minute debugging required on the launch site.","_LINK":"TVC-REQ-009"},"26":{"MID":"abc0c4200f0c4a34b0de6eddc6302a47","UID":"TVC-REQ-010","LEVEL":"L1","REQUIREMENT_TYPE":"Physical","TITLE":"Flight Computer Accessibility","APPLICABLE_SUBSYSTEM":"Avionics, Airframe","SUBTEAM_OWNER":"Structures","INDIVIDUAL_OWNER":"Structures Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Pre-Launch","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Inspection","STATUS":"Draft","STATEMENT":"For important flight computer debugging interfaces, such as flashing code and MCU reset, these interfaces shall be accessible during all pre-launch activities until the rocket is placed on the launch rail/pad.","RATIONALE":"This requirement ensures rapid debugging in the case of failures, and gives the option for quick fixes without major rocket de-integration.","_LINK":"TVC-REQ-010"},"27":{"MID":"c23b7033a5714d159aea0619df8ad320","UID":"TVC-REQ-011","LEVEL":"L1","REQUIREMENT_TYPE":"Interface","TITLE":"Flight Computer Clearance","APPLICABLE_SUBSYSTEM":"Avionics, Airframe","SUBTEAM_OWNER":"Structures, Electrical","INDIVIDUAL_OWNER":"Structures Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Pre-Launch","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Analysis","STATUS":"Draft","STATEMENT":"The avionics bay shall be able to fit all flight computer components in the body tube of the rocket, including any boards, wiring, connectors, power, antennas, etc...","RATIONALE":"This requirement ensures spacing requirements for the flight computer will be met.","_LINK":"TVC-REQ-011"},"28":{"MID":"708e504e1cea49f3b9525c52925e85d1","UID":"TVC-REQ-012","LEVEL":"L2","REQUIREMENT_TYPE":"Interface","TITLE":"Flight Computer Profile","APPLICABLE_SUBSYSTEM":"Avionics, Airframe","SUBTEAM_OWNER":"Structures, Electrical","INDIVIDUAL_OWNER":"Electrical Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Inspection","STATUS":"Draft","STATEMENT":"The flight computer stack bay shall match the max profile, when looking axially along the rocket, as shown in docs/Configuration/Flight Computer Stack Max Profile.png.","RATIONALE":"This requirement decomposes TVC-REQ-010, giving an exact profile the flight computer stack (Collection of X boards) may maximally reach. The max profile was found using solidworks basic geometry.","_LINK":"TVC-REQ-012"},"29":{"MID":"18b8b550ff814f5d882ed0fd9e3679f1","UID":"TVC-REQ-013","LEVEL":"L2","REQUIREMENT_TYPE":"Interface","TITLE":"Flight Computer Area","APPLICABLE_SUBSYSTEM":"Avionics, Airframe","SUBTEAM_OWNER":"Structures, Electrical","INDIVIDUAL_OWNER":"Electrical Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Inspection","STATUS":"Draft","STATEMENT":"The flight computer stack shall have a max footprint of 2.8 inches by 10 inches.","RATIONALE":"2.8 inches is the max width of the board, found from solidworks. The length is constrainted to 10 inches to prevent the rocket/avionics bay from lengthening too much, increasing mass.","_LINK":"TVC-REQ-013"},"30":{"MID":"c3c327d9547d42a6a47e6ebfea0bb710","UID":"TVC-REQ-014","LEVEL":"L1","REQUIREMENT_TYPE":"Physical","TITLE":"Max Dry Rocket Mass","APPLICABLE_SUBSYSTEM":"Airframe, Propulsion, Actuation, Avionics, Power, Recovery","SUBTEAM_OWNER":"Structures, Electrical","INDIVIDUAL_OWNER":"Systems Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Inspection","STATUS":"Draft","STATEMENT":"The max dry mass of the rocket (mass without motors) shall be a maximum of 1050 grams.","RATIONALE":"A simple, 1D simulation was put together in order to Validate this requirement. That simulation can be found in docs/Configuration/TVC-REQ-013 folder. This simple 1-D simulation is required, as OpenRocket cannot properly simulate the full flight of an unstable rocket. The mass of the rocket in the simulation was adjusted to find the absolute maximum mass that allowed for around 50 feet of altitude gain, with some tolerance. This ensures the rocket, assuming a mostly vertical flight, will not reach the ground before motor burnout.","_LINK":"TVC-REQ-014"},"31":{"MID":"3f1979305efb46b499bd6352f2cbfb80","UID":"TVC-REQ-015","LEVEL":"L2","REQUIREMENT_TYPE":"Physical","TITLE":"Max Gimbal Mass","APPLICABLE_SUBSYSTEM":"Actuation","SUBTEAM_OWNER":"Structures","INDIVIDUAL_OWNER":"Structures Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Inspection","STATUS":"Draft","STATEMENT":"The max mass of all gimbal components shall be a maximum of 350 grams.","RATIONALE":"Using previous program experience. From Scarlet (Gimbaled 2024-2025) the mass of the gimbal was ~200 grams, but increased to ~800 grams on HPRTVC. Seeing as the architecture of Gimbaled TVC (Being low powered) matches Scarlet, but has greater restrictions (Accuracy, Speed, etc..) the mass is taken from Scarlet, with increased tolerance to allow for improved design.","_LINK":"TVC-REQ-015"},"32":{"MID":"cd29667470e1432c8e46769c56968788","UID":"TVC-REQ-016","LEVEL":"L2","REQUIREMENT_TYPE":"Physical","TITLE":"Max Avionics Mass","APPLICABLE_SUBSYSTEM":"Avionics, Power","SUBTEAM_OWNER":"Structures","INDIVIDUAL_OWNER":"Structures Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Inspection","STATUS":"Draft","STATEMENT":"The max mass of all avionics components shall be a maximum of 450 grams.","RATIONALE":"Using previous program experience. From Scarlet (Gimbaled 2024-2025) the mass of the avionics was ~500 grams, but increased to ~800 grams on HPRTVC. In order to accomodate other rocket changes, such as an improved gimbal, the mass budget for the avionics bay is slightly reduced. This is assumed to be practical, considering electrical team goals to make a lightweight, compact flight computer.","_LINK":"TVC-REQ-016"},"33":{"MID":"7c6355a16d644e2e94ee27989aa61b02","UID":"TVC-REQ-017","LEVEL":"L2","REQUIREMENT_TYPE":"Physical","TITLE":"Max \"other\" mass","APPLICABLE_SUBSYSTEM":"Airframe, Recovery","SUBTEAM_OWNER":"Structures","INDIVIDUAL_OWNER":"Structures Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Inspection","STATUS":"Draft","STATEMENT":"The max mass of all non-gimbal, non-avionics components shall be a maximum of 250 grams. ","RATIONALE":"Considering TVC-REQ-014 and TVC-REQ-015, the remaining mass in order to meet TVC-REQ-013 is 250g. Seeing as the remaining mass includes airframe, nosecone, and recovery, this is likely a reasonable constraint, especially considering previous program experience.","_LINK":"TVC-REQ-017"},"34":{"MID":"fc3ccc0328ba4f6c933c69d7453c194c","UID":"TVC-REQ-018","LEVEL":"L1","REQUIREMENT_TYPE":"Functional","TITLE":"Specific Controls Shutoff Conditions","APPLICABLE_SUBSYSTEM":"Avionics, Flight_Software","SUBTEAM_OWNER":"Controls","INDIVIDUAL_OWNER":"Controls Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Powered Ascent","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"TBD","RESOLUTION_OWNER":"Controls Lead","RESOLUTION_PLAN":"Once a completed GNCSim architecture has been put together, and the Gimbaled TVC rocket is ready to simulate, a variety of unsafe conditions should be simulated via Monte Carlo (Rocket Angle from Vertical, Angular rates in Pitch, Yaw, and Roll). For each of these factors, a maximum safe condition shall be decided, based on whether the rocket can recover from the condition by the end of the burn of the motor. Because the values are a small change in software, this can be resolved later on in the design cycle. Additionally, GNCSim should simulate what happens after controls shutoff. GNCSim should consider cases of return back to 0, return back to 0 and cut power, just cutting power, etc...","RESOLUTION_DUE_DATE":"December 1st","VERIFICATION_METHOD":"Test","STATUS":"Draft","STATEMENT":"The rocket controls shall be turned off when unsafe conditions are reached. Unsafe conditions include: (1) Rocket [TBD_UnsafeDeg] degrees from vertical, (2) Rocket has [TBD_UnsafeRate] angular rate in Pitch/Yaw, (3) Rocket has [TBD_UnsafeRate2] angular rate in Roll. Controls shutoff invovles actuating the gimbal to the known 0 position, then cutting power from the gimbal actuators.","RATIONALE":"This meets the parent requirement, ensuring that controls are shutoff once angle, or rates, are too high to recover from. At this point, it is assumed the controls are not working as expected, and likely are contributing to rocket unsafe conditions. ","_LINK":"TVC-REQ-018"},"35":{"MID":"3f8e48e2b0b54ef2bb19a30c27cd5029","UID":"TVC-REQ-019","LEVEL":"L1","REQUIREMENT_TYPE":"Design Constraint","TITLE":"GNCSim for controls algorithm","APPLICABLE_SUBSYSTEM":"Avionics, Flight_Software","SUBTEAM_OWNER":"Controls","INDIVIDUAL_OWNER":"Controls Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Inspection","STATUS":"Draft","STATEMENT":"The controls team shall develop a full, closed-loop model of the Gimbaled TVC rocket in GNCSim in order find and tune the closed loop controls for the vehicle.","RATIONALE":"In order to derive a control loop algorithm, the team must use GNCSim to model the rocket, the control algorithm, and use GNCSim to evaluate the control algorithm (Stability, Response Time, Steady State Error, etc...)","_LINK":"TVC-REQ-019"},"36":{"MID":"e620e4b48064476baeffb92adb00a0d3","UID":"TVC-REQ-020","LEVEL":"L2","REQUIREMENT_TYPE":"Design Constraint","TITLE":"GNCSim Modelling Inclusions","APPLICABLE_SUBSYSTEM":"Avionics, Flight_Software","SUBTEAM_OWNER":"Controls","INDIVIDUAL_OWNER":"Controls Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Inspection","STATUS":"Draft","STATEMENT":"GNCSim shall model multiple rocket elements, including but not limited to: Simple dynamics, Aerodynamics, Sensors, Actuator, Wind, etc...","RATIONALE":"Modeling the above rocket elements will help ensure a complete rocket model and that all major factors affecting the rocket state/controls algorithm are accounted for. ","_LINK":"TVC-REQ-020"},"37":{"MID":"e5674417298d4f68a153b0cee9b16f65","UID":"TVC-REQ-021","LEVEL":"L2","REQUIREMENT_TYPE":"Interface","TITLE":"GNCSim Aerodynamics Requirements","APPLICABLE_SUBSYSTEM":"Avionics, Flight_Software","SUBTEAM_OWNER":"Aerodynamics","INDIVIDUAL_OWNER":"Aerodynamics Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Inspection","STATUS":"Draft","STATEMENT":"Aerodynamics shall provide a completed model of the aerodynamics characteristics of the rocket, in the form of a lookup table at various mach speeds and angles of attacks. These characteristics include but are not limited to: Cp location, Lift Coefficient, Drag Coefficient","RATIONALE":"Modeling the above rocket elements will help ensure a complete rocket model and that all major factors affecting the rocket state/controls algorithm are accounted for. ","_LINK":"TVC-REQ-021"},"38":{"MID":"19552a9d28614976914acd4a2b18ff9f","UID":"TVC-REQ-022","LEVEL":"L1","REQUIREMENT_TYPE":"Design Constraint","TITLE":"Control Loop Overall Architecture","APPLICABLE_SUBSYSTEM":"Avionics, Flight_Software","SUBTEAM_OWNER":"Controls","INDIVIDUAL_OWNER":"Controls Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Powered Ascent","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Inspection","STATUS":"Draft","STATEMENT":"The controls loop shall use a PID controller.","RATIONALE":"PID control is the essential, basic controller, which is the best choice for a smaller rocket with a relatively basic goal. ","_LINK":"TVC-REQ-022"},"39":{"MID":"496b5e370dd7406c947a89752c1d640f","UID":"TVC-REQ-023","LEVEL":"L1","REQUIREMENT_TYPE":"Design Constraint","TITLE":"Control Loop Overall Architecture","APPLICABLE_SUBSYSTEM":"Avionics, Flight_Software","SUBTEAM_OWNER":"Software","INDIVIDUAL_OWNER":"Software Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Test","STATUS":"Draft","STATEMENT":"Every state in the state machine shall have clearly defined entry and exit criteria. Implementation of the entry and exit criteria shall match the criteri and prevent any invalid state transitions (Ex: Transitions to other states when unintended)","RATIONALE":"Each state in a state machine must have a way to enter and exit. It is flight critical that the rocket does not enter a state when it is not intended for it to do so. For example, if the rocket were to enter the state pertaining to recovery prematurely, and prematurely deploy the parachute before motor burnout, that would be detrimental to the mission objectives.","_LINK":"TVC-REQ-023"},"40":{"MID":"b65c08f7297b47eca959e0081a329cb1","UID":"TVC-REQ-024","LEVEL":"L1","REQUIREMENT_TYPE":"Physical","TITLE":"Motor Burn Time","APPLICABLE_SUBSYSTEM":"Propulsion","SUBTEAM_OWNER":"Systems","INDIVIDUAL_OWNER":"Systems Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Powered Ascent","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Inspection","STATUS":"Draft","STATEMENT":"The motor shall have a burn time of at least three seconds.","RATIONALE":"In order to demonstratably show the rocket controlling its attitude, it must have a long enough burn time to give the control system time to correct any errors in atttitude. Assuming it takes the rocket ~1 second to clear the launch rail, a minimum of a three second burn time gives the rocket ~2 seconds to correct any errors in attitude. From previous program experience, this should be enough to discernebly notice whether the control system is reacting to the other, along with collecting enough data to do so.","_LINK":"TVC-REQ-024"},"41":{"MID":"02dafc70c10c4458b0838515770cfd92","UID":"TVC-REQ-025","LEVEL":"L2","REQUIREMENT_TYPE":"Physical","TITLE":"Gimbaled TVC Motor Selection","APPLICABLE_SUBSYSTEM":"Propulsion","SUBTEAM_OWNER":"Systems","INDIVIDUAL_OWNER":"Systems Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Powered Ascent","FLIGHT_ATTEMPT":"Flight 1","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Inspection","STATUS":"Draft","STATEMENT":"The motor for Gimbaled TVC shall be the G12ST.","RATIONALE":"The motor was chosen based off the Gimbaled TVC trade study, published in Notion under the Gimbaled TVC project docs (https://app.notion.com/p/LPRTVC-Motor-Trade-Study-3c5b2f334a1e804d9b0cca500c498f73?source=copy_link).","_LINK":"TVC-REQ-025"},"42":{"MID":"4075be889fa84997a022e08ad7f55c4b","UID":"TVC-REQ-026","LEVEL":"L1","REQUIREMENT_TYPE":"Physical","TITLE":"Constraining Motor in Gimbal","APPLICABLE_SUBSYSTEM":"Propulsion","SUBTEAM_OWNER":"Structures","INDIVIDUAL_OWNER":"Structures Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Pre-Launch","FLIGHT_ATTEMPT":"Flight 1","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Test","STATUS":"Draft","STATEMENT":"The motor shall be properly constrained in the rocket, where it does not fall out under normal pre-launch activities, at all times from pre-launch to end of the mision.","RATIONALE":"Constraining the motor is important to ensure flight operations go smoothly and the motor can properly transfer force to the vehicle.","_LINK":"TVC-REQ-026"},"43":{"MID":"7e59707a14d24e91b1e4fa5096e42add","UID":"TVC-REQ-027","LEVEL":"L1","REQUIREMENT_TYPE":"Functional","TITLE":"Parachute Release Conditions","APPLICABLE_SUBSYSTEM":"Recovery, Flight_Software, Avionics","SUBTEAM_OWNER":"Structures","INDIVIDUAL_OWNER":"Structures Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Parachute Descent","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Test","STATUS":"Draft","STATEMENT":"The recovery system shall be deployed at the minimum expected velocity of the rocket, which is also apogee. Once the barometer data has no readings greater than a previous reading for >0.5 seconds, the fire wire should be set off.","RATIONALE":"The parachute should be deployed at minumum velocity (apogee) to reduce loads on the chute and other recovery hardware. This condition can be most easily read by the barometer.","_LINK":"TVC-REQ-027"},"44":{"MID":"f1cf6231f1914a17b3218d6206935526","UID":"TVC-REQ-028","LEVEL":"L1","REQUIREMENT_TYPE":"Design Constraint","TITLE":"Rocket Airframe Material","APPLICABLE_SUBSYSTEM":"Airframe","SUBTEAM_OWNER":"Structures","INDIVIDUAL_OWNER":"Structures Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Analysis","STATUS":"Draft","STATEMENT":"The rocket shall use cardboard as the material for its airframe.","RATIONALE":"Carboard is a lightweight material common for Low Power rockets. It is less dense than blue tube, and from previous program experience it is well equipped to experience the expected loads ","_LINK":"TVC-REQ-028"},"45":{"MID":"542b10d87134412785823bf87dd853d4","UID":"TVC-REQ-029","LEVEL":"L1","REQUIREMENT_TYPE":"Design Constraint","TITLE":"Rocket Airframe and Nosecone Material","APPLICABLE_SUBSYSTEM":"Airframe","SUBTEAM_OWNER":"Structures","INDIVIDUAL_OWNER":"Structures Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Analysis","STATUS":"Draft","STATEMENT":"The rocket shall use no metal in the cardboard airframe, in the nosecone, and any gimbal components that are not constrained in the body tube.","RATIONALE":"NAR regulations do not allow metal in the externals of the rocket, this requirement decomposes the parent requirement to apply to specific components.","_LINK":"TVC-REQ-029"},"46":{"MID":"86e095e729484d02b6f9c7212c6c2cf6","UID":"TVC-REQ-030","LEVEL":"L1","REQUIREMENT_TYPE":"Safety","TITLE":"Range Safety Constraints","APPLICABLE_SUBSYSTEM":"N_A","SUBTEAM_OWNER":"Controls","INDIVIDUAL_OWNER":"Controls Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"TBD","RESOLUTION_OWNER":"Controls Lead","RESOLUTION_PLAN":"The requirement lists the resolution plan. GNCSim shall simulate the rocket dispersion under thrust to close this requirement.","RESOLUTION_DUE_DATE":"September 30th, 2026","VERIFICATION_METHOD":"Analysis","STATUS":"Draft","STATEMENT":"The rocket launch range, [TBD_LaunchRange], shall be derived via Monte Carlo flight dynamic simulation. The vehicle's max TVC limit, aerodynamic load range, maximum determined failire modes should be considered. For range safety, altitude shall not be a consideration (At any range, the rocket is deemed unsafe, even if at a higher altitude)","RATIONALE":"This requirement decomposes the parent requirement by specifically requiring dynamic analysis to find launch range, and setting specific constraints.","_LINK":"TVC-REQ-030"},"47":{"MID":"95c56e1476694dd4a754093cb7f385fe","UID":"TVC-REQ-031","LEVEL":"L1","REQUIREMENT_TYPE":"Safety","TITLE":"Launch Rail Usage","APPLICABLE_SUBSYSTEM":"Ground_Systems","SUBTEAM_OWNER":"Structures","INDIVIDUAL_OWNER":"Structures Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"Flights 1-3","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Inspection","STATUS":"Draft","STATEMENT":"The mission shall use a team-built launch rail and team-built method to ignite the rocket, where both can be placed wherever without any problem.  ","RATIONALE":"This requirement ensures range safety will be met by allowing the rocket to be placed anywhere on the launch site. ","_LINK":"TVC-REQ-031"},"48":{"MID":"d491bece3d7a4ab282e88d9023738a9f","UID":"TVC-REQ-032","LEVEL":"L2","REQUIREMENT_TYPE":"Safety","TITLE":"Ground Ignition System","APPLICABLE_SUBSYSTEM":"Ground_Systems","SUBTEAM_OWNER":"Structures, Electrical, Software","INDIVIDUAL_OWNER":"Structures Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"TBR","RESOLUTION_OWNER":"Electrical","RESOLUTION_PLAN":"Once launch range has been established, the exact microcontroller and wireless communication method will be decided. For example, if launch range is expected to be over 300 feet, the Raspberry Pi wifi capabilities may not be sufficient.","RESOLUTION_DUE_DATE":"October 31st, 2026","VERIFICATION_METHOD":"Inspection","STATUS":"Draft","STATEMENT":"The team-built rocket ignition method shall use a Commerical off the shelf (COTS) micrcontroller (Such as Raspberry Pi), using an e-match and supporting components (Ex: Wiring). The micrcontroller must have built in wireless communication capabilities or include a component (such as an external radio) that allows it to do so. The wireless communication method shall be: [TBD_WirelessCommMethod].","RATIONALE":"Using a COTS microcontroller reduces complexity of the ground ignition system, and wireless communication is a must-have to allow the launch range to be met. The exact method of sending the ignition signal is TBD depending on how large the range actually is.","_LINK":"TVC-REQ-032"},"49":{"MID":"77eefff58e1f4605a98d20c2adebd3ad","UID":"TVC-REQ-033","LEVEL":"L1","REQUIREMENT_TYPE":"Design Constraint","TITLE":"Removable launch rail ","APPLICABLE_SUBSYSTEM":"Ground_Systems","SUBTEAM_OWNER":"Structures","INDIVIDUAL_OWNER":"Structures Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Inspection","STATUS":"Draft","STATEMENT":"The designed team-built launchpad shall have a removable launch rail.","RATIONALE":"This ensures the team must only design/manufacture one launchpad, that is both applicable for launches with and without using a launch rail.","_LINK":"TVC-REQ-033"},"50":{"MID":"b676a3fbf71642ab85336e96aa333c5b","UID":"TVC-REQ-034","LEVEL":"L1","REQUIREMENT_TYPE":"Physical","TITLE":"Black Powder Used","APPLICABLE_SUBSYSTEM":"Recovery","SUBTEAM_OWNER":"Structures","INDIVIDUAL_OWNER":"Structures Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"TBD","RESOLUTION_OWNER":"Structures","RESOLUTION_PLAN":"Black Powder testing, where the entire recovery system is placed in the rokcet tube and black powder is ejected on the ground, will determine the sufficient amount of black powder.","RESOLUTION_DUE_DATE":"October 30th, 2026","VERIFICATION_METHOD":"Demonstration","STATUS":"Draft","STATEMENT":"The rocket shall use a sufficient amount of black powder in order to effectively release the parachute system, [TBD_BlackPowder] grams at a minimum.","RATIONALE":"An insufficient amount of black powder will lead to a stuck nosecone and a failure to effectively recover the rocket.","_LINK":"TVC-REQ-034"},"51":{"MID":"f1cf4ec66ffd4684b2be03c581e6ebb7","UID":"TVC-REQ-035","LEVEL":"L1","REQUIREMENT_TYPE":"Design Constraint","TITLE":"Recovery Electrical Independence","APPLICABLE_SUBSYSTEM":"Recovery, Avionics","SUBTEAM_OWNER":"Electrical","INDIVIDUAL_OWNER":"Electrical Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Parachute Descent","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Inspection","STATUS":"Draft","STATEMENT":"The flight computer's recovery electrical power system shall operate independently from other board functions such as primariy flight control, using dedicated poewr rails and isolated distribution paths.","RATIONALE":"Effective recovery means ensuring the fire wire is never set off accidentally. This is also a safety concern. Power system independence reduces the chance of a design error causing current/voltage surges.","_LINK":"TVC-REQ-035"},"52":{"MID":"7bd531880cfd411ba3260689074423e6","UID":"TVC-REQ-036","LEVEL":"L1","REQUIREMENT_TYPE":"Physical","TITLE":"Recovery Parachute Sizing","APPLICABLE_SUBSYSTEM":"Recovery","SUBTEAM_OWNER":"Structures","INDIVIDUAL_OWNER":"Structures Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Parachute Descent","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Inspection","STATUS":"Draft","STATEMENT":"The descent rate of the rocket shall be under 20 feet per second while under parachute","RATIONALE":"20 feet per second is model rocketry standard parachute descent rate to ensure a safe recovery and low ground hit speed.","_LINK":"TVC-REQ-036"},"53":{"MID":"f55af349b02541d1964c3242a744a004","UID":"TVC-REQ-037","LEVEL":"L1","REQUIREMENT_TYPE":"Physical","TITLE":"Harness/Wiring Effective Routing","APPLICABLE_SUBSYSTEM":"Airframe, Avionics, Actuation, Recovery","SUBTEAM_OWNER":"Structures","INDIVIDUAL_OWNER":"Structures Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"All","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Inspection","STATUS":"Draft","STATEMENT":"All wiring in the rocket shall be tied off (mounted) at a maximum distance between ties of 0.75 inches.","RATIONALE":"NASA STD-8739.4 gives standards for wire harnesses, and tells us that at a wire diameter of 0.25 inches or less, maximum tie off distance should be 0.75 inches. While not all wire gauges have been decided, it is likely that most wries will end up smaller than 0.25 inches, so this requirement is applied to the entire rocket. This is decomposed from TVC-MO-007, where wires coming loose is considerd \"disassembly\".","_LINK":"TVC-REQ-037"},"54":{"MID":"805d113e043f4f38ab97c7325890b9f1","UID":"TVC-REQ-038","LEVEL":"L1","REQUIREMENT_TYPE":"Functional","TITLE":"Launch State Transition","APPLICABLE_SUBSYSTEM":"Avionics, Flight_Software","SUBTEAM_OWNER":"Software","INDIVIDUAL_OWNER":"Software Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Pre-Launch","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Test","STATUS":"Draft","STATEMENT":"The flight software shall detect launch, and once it does transition the state machine to powered ascent (Where active controls will be active). The conditions to detect launch shall be: Acceleration above +0.5G for 50 ms.","RATIONALE":"According to OpenRocket, the thrust:weight ratio off the pad is ~2. Removing gravity, this is 1G acceleration. Applying a scaling factor of 0.5, which balances sensitivty and gives a tolerance for acceleration, this gives a launch condition of +0.5G. 50ms ensures that random disturbances do not trigger the launch (Control loop runs at >20Hz), while also ensuring that launch is detected quickly, reducing time when the rocket does not control itself.","_LINK":"TVC-REQ-038"},"55":{"MID":"58e5887e5e37433b969cd9194b96a11a","UID":"TVC-REQ-039","LEVEL":"L2","REQUIREMENT_TYPE":"Performance","TITLE":"Battery performance and life","APPLICABLE_SUBSYSTEM":"Avionics, Power","SUBTEAM_OWNER":"Electrical","INDIVIDUAL_OWNER":"Electrical Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Pre-Launch","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Analysis","STATUS":"Draft","STATEMENT":"The vehicle battery shall last at least two hours under nominal expected operating conditions. Nominal operating conditions include power being on for 2 hours, with at least half an hour of actuation testing and other misc. testing and launch activities.","RATIONALE":"In order to provide turnaround in two hours, it will be difficult to do so if having to replace the battery often. Ensuring the battery needs to be replaced, at a maximum, once between flights ensures there is no time wasted between launch turnaround time.","_LINK":"TVC-REQ-039"},"56":{"MID":"d4f3b5e11b6e4ec69694611ef2026437","UID":"TVC-REQ-040","LEVEL":"L1","REQUIREMENT_TYPE":"Functional","TITLE":"Overcurrent/Reverse Polarity Protections","APPLICABLE_SUBSYSTEM":"Avionics, Power","SUBTEAM_OWNER":"Electrical","INDIVIDUAL_OWNER":"Electrical Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Pre-Launch","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Demonstration","STATUS":"Draft","STATEMENT":"The flight computer, and other supporting boards, shall have protection against overcurrent and reverse voltage. ","RATIONALE":"A common club mistake has been plugging incorrect batteries/reversing battery connectors. To help prevent these mistakes crippling launch, boards must not be affected by incorrect power being plugged in.","_LINK":"TVC-REQ-040"},"57":{"MID":"d73e422b84824eb38b3e2a0b32fa75c5","UID":"TVC-REQ-041","LEVEL":"L1","REQUIREMENT_TYPE":"Functional","TITLE":"Labeling Wires Before Launch","APPLICABLE_SUBSYSTEM":"Avionics, Power, Actuation","SUBTEAM_OWNER":"Electrical","INDIVIDUAL_OWNER":"Electrical Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Pre-Launch","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Inspection","STATUS":"Draft","STATEMENT":"Every single cable that is used for launch, ranging from servo cables for the actuators, to CAN connection, to JTAG connectors, shall be labeled before leaving for the launch site.","RATIONALE":"Cables can be plugged in incorrectly, and labeling all of them beforehand gives time to double check connections beforehand and prevent on-site quick decisions from de-railing launches. This also helps improve turnaround as less time is spent deciding exactly which cables need to be plugged in where.","_LINK":"TVC-REQ-041"},"58":{"MID":"7650c5ddb1a048cab3a7490ed0ba6b19","UID":"TVC-REQ-042","LEVEL":"L1","REQUIREMENT_TYPE":"Design Constraint","TITLE":"Gimbal Replaceable Motor Case","APPLICABLE_SUBSYSTEM":"Propulsion, Actuation","SUBTEAM_OWNER":"Structures","INDIVIDUAL_OWNER":"Structures Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Pre-Launch","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Demonstration","STATUS":"Draft","STATEMENT":"The gimbal design shall use an easily replaceable motor holder.","RATIONALE":"The motor holder, historically, has warped under heating from the motor. Instead of requiring the motor holder to be designed to handle the heat, this requirement allows warping, and replacing the motor in the engine is a motor of replacing the motor and holder as a unit.","_LINK":"TVC-REQ-042"},"59":{"MID":"bfe519f2885c4cf2a10135b6a7411f14","UID":"TVC-REQ-043","LEVEL":"L1","REQUIREMENT_TYPE":"Functional","TITLE":"No last Minute Changes","APPLICABLE_SUBSYSTEM":"N_A","SUBTEAM_OWNER":"Systems","INDIVIDUAL_OWNER":"Systems Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Pre-Launch","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Inspection","STATUS":"Draft","STATEMENT":"The rocket and supporting systems shall prevent any last minute changes made to the design, structures, flight software, avionics, etc... Note: Last minute is defined differently for different subsystems.","RATIONALE":"Last minute changes are easy ways to introduce errors into the rocket. Last minute changes rarely can be tested, and if done quickly are more likely to contain mistakes. ","_LINK":"TVC-REQ-043"},"60":{"MID":"f61478de6d714a9496c9da361d2e1f45","UID":"TVC-REQ-044","LEVEL":"L2","REQUIREMENT_TYPE":"Functional","TITLE":"Flight Software Changes","APPLICABLE_SUBSYSTEM":"Flight_Software","SUBTEAM_OWNER":"Software","INDIVIDUAL_OWNER":"Software Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Pre-Launch","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Inspection","STATUS":"Draft","STATEMENT":"The flight software and supporting systems that the rocket will use shall prevent changes less than 0.5 weeks before the expected launch date. Tracking for flight software shall be done using github, and no commits from after the 0.5 week cutoff shall be used in the flight software for launch. For each version of flight software that is flown on a rocket, it must be tagged in Github with the flight number. (Tag: Flight #).","RATIONALE":"This requirement decomposes the parent requirement to require a specific cutoff for changes to the flight software, along with requiring tags to improve traceability.","_LINK":"TVC-REQ-044"},"61":{"MID":"a84b0c44349e4205bfef90052e505a53","UID":"TVC-REQ-045","LEVEL":"L1","REQUIREMENT_TYPE":"Functional","TITLE":"Flight Computer Controls Ability","APPLICABLE_SUBSYSTEM":"Avionics, Flight_Software","SUBTEAM_OWNER":"Electrical","INDIVIDUAL_OWNER":"Electrical Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Powered Ascent","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"TBD","RESOLUTION_OWNER":"Controls","RESOLUTION_PLAN":"Need to find required control loop update rate, Requirement TVC-REQ-047 lists the full completion plan to get this value.","RESOLUTION_DUE_DATE":"Refer to TVC-REQ-047","VERIFICATION_METHOD":"Test","STATUS":"Draft","STATEMENT":"The flight computer shall be capable of running the controls algorithm at the required rate (Refer to TVC-REQ-047). It must also include all required minimum sensors and be able to read sensor data. Minimum sensors: IMU, Magnetometer, Barometer, GPS","RATIONALE":"In order to run on-board controls, the flight computer must do so. It shall not be a limiting factor for the control loop rate. The flight computer also must have the required sensors to do GNC.","_LINK":"TVC-REQ-045"},"62":{"MID":"bc41c9da96c54ee2ac30c2a9ddb9178d","UID":"TVC-REQ-046","LEVEL":"L1","REQUIREMENT_TYPE":"Functional","TITLE":"Flight Computer TVC Ability","APPLICABLE_SUBSYSTEM":"Avionics, Flight_Software, Actuation","SUBTEAM_OWNER":"Electrical","INDIVIDUAL_OWNER":"Electrical Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Powered Ascent","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"TBR","RESOLUTION_OWNER":"Controls lead","RESOLUTION_PLAN":"Once controls has resolved the minimum Gimbal Velocity, this help establish how quickly the update rate of the gimbal must be. Refer to TVC-REQ-006 for a more detailed resolution plan.","RESOLUTION_DUE_DATE":"Refer to TVC-REQ-006","VERIFICATION_METHOD":"Test","STATUS":"Draft","STATEMENT":"The flight computer shall be capable of controlling the actuators for the gimbal. It shall be able to send commands in order to meet minimum requirements for speed of the gimbal (TVC-REQ-006), [TBD_GimbalVelocity]","RATIONALE":"The flight computer must be able to control the gimbal to allow for effective closed loop on-board controls.","_LINK":"TVC-REQ-046"},"63":{"MID":"e10e980b2c7f41c997657de7afde58bb","UID":"TVC-REQ-047","LEVEL":"L1","REQUIREMENT_TYPE":"Performance","TITLE":"Flight loop update rate","APPLICABLE_SUBSYSTEM":"Avionics, Flight_Software","SUBTEAM_OWNER":"Software","INDIVIDUAL_OWNER":"Software Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Powered Ascent","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"TBD","RESOLUTION_OWNER":"Controls Lead, Ilan V.","RESOLUTION_PLAN":"Need to consider Nyquist Criterion, etc... in order to decide proper update rate to allow for a controller that updates quickly enough to ensure closed loop controls can be achieved.","RESOLUTION_DUE_DATE":"September 18","VERIFICATION_METHOD":"Demonstration","STATUS":"Draft","STATEMENT":"The flight software loop shall run at a minimum of [TBD_UpdateRate] Hz.","RATIONALE":"Need to have a minumum control loop run in order to ensure the TVC is reacting quickly enough.","_LINK":"TVC-REQ-047"},"64":{"MID":"a394cf25bd5243ddaaaaf954c59e8638","UID":"TVC-REQ-048","LEVEL":"L2","REQUIREMENT_TYPE":"Performance","TITLE":"Sensor Update Rate","APPLICABLE_SUBSYSTEM":"Avionics, Flight_Software","SUBTEAM_OWNER":"Software","INDIVIDUAL_OWNER":"Software Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Powered Ascent","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"TBD","RESOLUTION_OWNER":"Controls","RESOLUTION_PLAN":"Need to find required control loop update rate, Requirement TVC-REQ-047 lists the full completion plan to get this value.","RESOLUTION_DUE_DATE":"Refer to TVC-REQ-047","VERIFICATION_METHOD":"Demonstration","STATUS":"Draft","STATEMENT":"All sensors shall have a minumum udpate rate of [TBD_UpdateRate] Hz.","RATIONALE":"Controls requires a minimum update rate of the control loop, and the controllers must follow this update rate to support this control loop rate.","_LINK":"TVC-REQ-048"},"65":{"MID":"661e53a46720498482b13929a514f3ca","UID":"TVC-REQ-049","LEVEL":"L1","REQUIREMENT_TYPE":"Functional","TITLE":"Kalman Filter Usage","APPLICABLE_SUBSYSTEM":"Avionics, Flight_Software","SUBTEAM_OWNER":"Software, Controls","INDIVIDUAL_OWNER":"Software Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Powered Ascent","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Demonstration","STATUS":"Draft","STATEMENT":"The flight software shall implement a Kalman filter for state estimation.","RATIONALE":"Kalman filter is an industry standard method of improving the accuracy of state estimation, which will improve the quality of the rocket closed loop controls.","_LINK":"TVC-REQ-049"},"66":{"MID":"d7e56cc2f4cf404aa6dd162f06b5436e","UID":"TVC-REQ-050","LEVEL":"L1","REQUIREMENT_TYPE":"Performance","TITLE":"Flight Algorithm Stability","APPLICABLE_SUBSYSTEM":"Avionics, Flight_Software","SUBTEAM_OWNER":"Controls","INDIVIDUAL_OWNER":"Controls Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Powered Ascent","FLIGHT_ATTEMPT":"All","OPEN_ITEM_STATUS":"None","VERIFICATION_METHOD":"Analysis","STATUS":"Draft","STATEMENT":"The controls algorithm shall be demonstratably stable over the course of the rockt's flight, within the expected controls range (Max angle of attack before controls is turned off).","RATIONALE":"In order to effectively stabilize the rocket, the flight algorithm must be stable over the course of the flight. Oscillations, exponential increases, etc... are all indicative of non-stable controls algorithm.","_LINK":"TVC-REQ-050"},"67":{"MID":"7d0c74c8f7144f4bb1017be16dac446d","UID":"TVC-REQ-051","LEVEL":"L1","REQUIREMENT_TYPE":"Functional","TITLE":"Controls algorithm delay","APPLICABLE_SUBSYSTEM":"Avionics, Flight_Software","SUBTEAM_OWNER":"Software, Controls","INDIVIDUAL_OWNER":"Software Lead","VEHICLE_CONFIGURATION":"TVC-F1","MISSION_PHASE":"Powered Ascent","FLIGHT_ATTEMPT":"Flights 1-3","OPEN_ITEM_STATUS":"TBR","RESOLUTION_OWNER":"Structures","RESOLUTION_PLAN":"Waiting for a decision on launch rail height. Once rail height has been found, need to research how to simulate launch rail friction/loads for rocket, to find how long it would take the rocket to clear the rail. ","RESOLUTION_DUE_DATE":"November 30th","VERIFICATION_METHOD":"Demonstration","STATUS":"Draft","STATEMENT":"The controls algorithm shall be delayed by [TBD_DelaySeconds] after launch is detected, before active controls are activated.","RATIONALE":"Need to set a specific delay before the rocket begins controlling the gimbal, in order for the rocket to clear the rail before starting active controls. Use rail length to determine the length.","_LINK":"TVC-REQ-051"}};
